const repo="repr0bated/odbus-verified";
const nums=[16,18,19,20,21,34,36];
const rs=await Promise.allSettled(nums.map(n=>tools.mcp__codex_apps__github_get_pr_info({repository_full_name:repo,pr_number:n})));
for(let i=0;i<rs.length;i++){const r=rs[i];if(r.status==="fulfilled"){const v=r.value.structuredContent; store("close_pr_"+nums[i],v);text({number:nums[i],keys:v?Object.keys(v):null,state:v?.state,head_sha:v?.head_sha});}else text({number:nums[i],error:String(r.reason)});}

const repo="repr0bated/odbus-verified";
const reason={
16:"The newer source removes the seven legacy router/skills contract files and uses the successor threetched implementation.",
18:"The fresh bridge module graph replaces the old dispatch, build and generation paths.",
19:"The old identity/mutation/MCP dispatch files are unlinked from the successor bridge module graph.",
20:"The old schema, task-elevation and router modules are unlinked or removed in the successor.",
21:"The successor explicitly disables the old automatic integration-test surface and provides fresh bridge contract tests.",
34:"Both changed paths are byte-identical in the successor; this extraction adds no source beyond that target.",
36:"All 24 changed paths are byte-identical in the successor; this extraction adds no source beyond that target."
};
const receipts=[];
for (const n of [16,18,19,20,21,34,36]){
 const p=load("close_pr_"+n); if(!p||p.state!=="open"){text({n,skipped:true});continue;}
 const body=(p.body||"")+"\n\n---\nResolution (2026-10-30): superseded by #46.\n\nThe owner selected newer source, including the hackathon code, as the authority. PR #46 at `380f692dceb6a73b2a5e6567dbd5955ce99786dd` contains hackathon HEAD `2a6e40e` and its newer bridge successor. "+reason[n]+" Source comparison and Jev (`jev-1.14.0`) both support superseding this old delivery PR.\n\nClosing preserves the branch and review history. This does not assert that every historical review concern is fixed; any independent defect demonstrated in retained code belongs against #46/current source.";
 const r=await tools.mcp__codex_apps__github_update_pull_request({repository_full_name:repo,pr_number:n,body,state:"closed"});
 const v=r.structuredContent; receipts.push({number:n,state:v?.state,url:v?.url});text(receipts.at(-1));
}
store("superseded_receipts",receipts);

