const body = "This integrates the hackathon history (`2a6e40e`) and its newer fresh bridge successor. The owner selected newer source over older architectural prose. The hackathon tree is unchanged, and the fresh bridge module graph remains authoritative.

The repair commit preserves applicable blob/validator, Cozo, cognitive checkpoint, provider-message, workflow-schema and bounded SSH-draining fixes. Atomic bridge batches reject nontransactional method calls before effects, state subscriptions capture history and live receivers together, lag returns `DataLoss`, and `GetState` returns state/hash/cursor from one commit boundary. Contract fixtures retain their bound TCP listeners; accidental HTML is removed. PR #45's cloud setup fix is merged into this branch.

Older recovery/extraction PRs are superseded as delivery branches. This does not certify every old finding fixed. [The source-first reconciliation record](https://github.com/repr0bated/odbus-verified/blob/6276a187a0ca3b539689f4a42917977e375ae55c/docs/reviews/pr-reconciliation-20261030.json) preserves all original unresolved thread links, current-source findings, and the native Jev (`jev-1.14.0`) relevance judgments. WISHLIST OD-125 tracks remaining concerns, including privileged notebook capture, storage retention, FUSE inode reuse, network recovery/admission and concurrent golden preparation. No old dispatcher or storage architecture was restored to satisfy obsolete findings.

Validation: independent source review accepted the final patch after reverting a blanket ShellExecutor disable and repairing the state/cursor race. The initial scoped GNU build passed (12m36s). The final locked GNU build at `6276a187`, including direct consumer `op-web`, is running. Tests, Clippy and formatting commands were not run under the owner's manual/on-request policy. Nothing was installed, sealed, deployed or restarted.";
store("pr46_body_pre_final",body);
const r=await tools.mcp__codex_apps__github_update_pull_request({repository_full_name:"repr0bated/odbus-verified",pr_number:46,title:"Integrate the fresh bridge and retained review fixes",body});text({number:r.structuredContent?.number,state:r.structuredContent?.state,head:r.structuredContent?.head_sha});

const pending=load("pending_old_prs");
const rs=await Promise.allSettled(pending.map(p=>tools.mcp__codex_apps__github_get_pr_info({repository_full_name:"repr0bated/odbus-verified",pr_number:p.number})));
const ready=[];
rs.forEach((r,i)=>{if(r.status!=="fulfilled"||!r.value.structuredContent){text({number:pending[i].number,error:String(r.reason||"missing response")});return;}const p=r.value.structuredContent;if(p.head_sha!==pending[i].head_sha){text({number:p.number,changed:true,head:p.head_sha});return;}if(p.state!=="open"){text({number:p.number,state:p.state});return;}ready.push(p);});
store("ready_to_supersede",ready);
text({ready:ready.map(p=>p.number),count:ready.length});

const reasons={
10:"The recovery head b28a343 is already an ancestor of the hackathon history and PR #46.",
11:"Compatible canonicalization and checked blob-publication fixes were ported to the successor; obsolete bridge restoration is excluded.",
12:"Projection allocation and SSH stderr-draining fixes were ported. Retained Snowball transfer/retention and dormant projection concerns are recorded against current source.",
13:"Compatible model-refresh and workflow attribution/history-ordering fixes were ported. Remaining store ownership and aggregate-bound concerns stay recorded.",
14:"The successor removes old binary namespace/dispatch paths. Current retained plugin compatibility concerns are recorded without restoring the old architecture.",
15:"Current source already supersedes several endpoint/type findings; the unchanged-gateway fix is ported. Remaining provider/dispatcher concerns are recorded.",
17:"The retained workflow step schema was tightened; findings about removed filesystem/bridge dispatch implementations are superseded.",
22:"Current code supersedes the old union-generator finding. The retained FUSE inode type-reuse concern is explicitly recorded; MCP is not declared absent merely because older prose said so.",
23:"Compatible checkpoint publication, Qdrant completion and link-ordering fixes were ported; old cognitive bridge admission paths are unlinked.",
26:"Provider adapters now preserve ordered system messages. Old cognitive bridge admission findings target replaced dispatch code.",
27:"The successor's current runtime code governs. The proposed blanket ShellExecutor disable was rejected because it removed retained root-gated functionality; policy and runtime concerns are recorded for compatible current-source repair.",
28:"The successor changes default web/bridge wiring and keeps the legacy door/relay outside that compiled/default path. Opt-in legacy concerns remain recorded.",
30:"Configuration findings were checked against current consumers; outdated interface, provider and retired-service demands are superseded. Current provisioning/admission concerns remain recorded.",
31:"The newer identity/bootstrap helpers supersede the older missing-helper/lifecycle layout. Current boot readiness still requires its own runtime validation.",
32:"The newer scripts supersede old root-sourced-environment findings. Root notebook capture and OVS restart concerns remain explicitly recorded.",
33:"The newer router/native provenance and FUSE script replace older layout findings. Interrupted default-route recovery remains recorded as a current defect.",
35:"Current interface/admission, exposure and rollback concerns are preserved against successor source. Closing this carrier does not assert they are fixed.",
37:"The newer golden builder replaces old provenance/layout findings. Concurrent shared-golden preparation remains explicitly recorded against current code.",
38:"Compatible vendored JSON Schema correctness fixes were ported. The newer native implementation and provenance take precedence over historical patch/pin restoration.",
42:"The newer provisioning code rejects the old privileged-group option and removes the old grant rewrite. Standalone retention/EFI and current lifecycle concerns remain recorded.",
43:"Root capture containment, managed-chunk lifecycle and pending visibility concerns remain recorded against current source; removed-script and missing-skill claims were reassessed."
};
const receipts=[];
for (const p of load("ready_to_supersede")){
 const body=(p.body||"")+"\n\n---\nResolution (2026-10-30): superseded as a delivery PR by #46.\n\nThe owner selected newer source and hackathon code as authoritative. PR #46 contains the hackathon history and the newer bridge, with compatible current-source repairs published at `6276a187a0ca3b539689f4a42917977e375ae55c`. "+reasons[p.number]+"\n\n[Current-source reconciliation, native Jev relevance judgments, and all historical unresolved thread links](https://github.com/repr0bated/odbus-verified/blob/6276a187a0ca3b539689f4a42917977e375ae55c/docs/reviews/pr-reconciliation-20261030.json) are retained, with follow-up work in WISHLIST OD-125. Closing this obsolete carrier is not a claim that every review finding is fixed or that the code is deployed. Branch and review history are preserved.";
 const r=await tools.mcp__codex_apps__github_update_pull_request({repository_full_name:"repr0bated/odbus-verified",pr_number:p.number,body,state:"closed"});
 const v=r.structuredContent;const receipt={number:p.number,state:v?.state,url:v?.url};receipts.push(receipt);text(receipt);store("remaining_superseded_receipts",receipts);
}

